#include <zephyr/kernel.h>
#include <zephyr/ztest.h>

#define STACK_SIZE (512 + CONFIG_TEST_EXTRA_STACK_SIZE)

static K_THREAD_STACK_DEFINE(tstack, STACK_SIZE);
static struct k_thread tdata;
static int thread_ret;

K_MUTEX_DEFINE(kmutex);
K_MUTEX_DEFINE(kmutex_prio_inv);

/* high priority thread */
static K_THREAD_STACK_DEFINE(tstack_high, STACK_SIZE);
static struct k_thread tdata_high;
/* medium priority thread */
static K_THREAD_STACK_DEFINE(tstack_med, STACK_SIZE);
static struct k_thread tdata_med;
/* low priority thread */
static K_THREAD_STACK_DEFINE(tstack_low, STACK_SIZE);
static struct k_thread tdata_low;

static volatile int high_prio_run_count;
static volatile int med_prio_run_count;
static volatile int low_prio_run_count;

#define THREAD_HIGH_PRIO 8
#define THREAD_MED_PRIO 9
#define THREAD_LOW_PRIO 10

/* Priority inversion test threads */
static void high_prio_thread(void *p1, void *p2, void *p3)
{
	ARG_UNUSED(p1);
	ARG_UNUSED(p2);
	ARG_UNUSED(p3);

	/* This thread will be blocked by the low priority thread */
	high_prio_run_count++;
	zassert_true(k_mutex_lock(&kmutex_prio_inv, K_MSEC(100)) == 0,
		     "High priority thread failed to get mutex");

	/* The medium priority thread should have run at this point */
	zassert_true(med_prio_run_count == 1,
		     "Medium priority thread did not run");

	k_mutex_unlock(&kmutex_prio_inv);
}

static void med_prio_thread(void *p1, void *p2, void *p3)
{
	ARG_UNUSED(p1);
	ARG_UNUSED(p2);
	ARG_UNUSED(p3);

	/*
	 * This thread should run while the high priority thread is
	 * waiting for the mutex.
	 */
	med_prio_run_count++;
	zassert_true(low_prio_run_count == 1,
		     "Low priority thread did not run first");
	zassert_true(high_prio_run_count == 1,
		     "High priority thread did not run before medium");
}

static void low_prio_thread(void *p1, void *p2, void *p3)
{
	ARG_UNUSED(p1);
	ARG_UNUSED(p2);
	ARG_UNUSED(p3);

	/* Take the mutex */
	zassert_true(k_mutex_lock(&kmutex_prio_inv, K_NO_WAIT) == 0,
		     "Low priority thread failed to get mutex");

	low_prio_run_count++;

	/*
	 * Let the other threads run. The high priority thread will
	 * preempt this thread and then block on the mutex. The medium
	 * priority thread will then run to completion. Then, this thread
	 * will be boosted to the high priority thread's priority and
	 * will run again.
	 */
	k_busy_wait(10 * 1000); /* 10 ms */

	/*
	 * The medium priority thread should have run at this point,
	 * and the high priority thread should be blocked.
	 */
	zassert_true(med_prio_run_count == 1,
		     "Medium priority thread did not run");

	k_mutex_unlock(&kmutex_prio_inv);
}

/**
 * @brief Test complex priority inversion scenario
 *
 * This test creates three threads with high, medium, and low priorities.
 * - The low priority thread takes a mutex.
 * - The high priority thread attempts to take the same mutex and blocks.
 * - The medium priority thread runs.
 * - The low priority thread's priority is elevated to the high priority
 *   thread's priority, allowing it to run and release the mutex.
 * - The high priority thread can then acquire the mutex.
 *
 * @ingroup kernel_mutex_tests
 */
static void test_complex_inversion(void)
{
	high_prio_run_count = 0;
	med_prio_run_count = 0;
	low_prio_run_count = 0;

	k_mutex_init(&kmutex_prio_inv);

	/* Create the low priority thread */
	k_tid_t low_tid = k_thread_create(&tdata_low, tstack_low, STACK_SIZE,
					  low_prio_thread, NULL, NULL, NULL,
					  THREAD_LOW_PRIO, 0, K_NO_WAIT);

	/* Create the medium priority thread */
	k_tid_t med_tid = k_thread_create(&tdata_med, tstack_med, STACK_SIZE,
					  med_prio_thread, NULL, NULL, NULL,
					  THREAD_MED_PRIO, 0, K_NO_WAIT);

	/* Create the high priority thread */
	k_tid_t high_tid = k_thread_create(&tdata_high, tstack_high, STACK_SIZE,
					   high_prio_thread, NULL, NULL, NULL,
					   THREAD_HIGH_PRIO, 0, K_NO_WAIT);

	/* Wait for all threads to complete */
	k_thread_join(low_tid, K_FOREVER);
	k_thread_join(med_tid, K_FOREVER);
	k_thread_join(high_tid, K_FOREVER);

	zassert_true(low_prio_run_count == 1, "Low priority thread did not run");
	zassert_true(med_prio_run_count == 1, "Medium priority thread did not run");
	zassert_true(high_prio_run_count == 1, "High priority thread did not run");
}

/**
 * @brief Test defining a mutex
 *
 * @ingroup kernel_mutex_tests
 *
 * @see K_MUTEX_DEFINE()
 */
static void test_mutex_define(void)
{
	/*This test case is to test whether the mutex is defined
	 * and initialized properly.
	 */
	zassert_equal(k_mutex_lock(&kmutex, K_NO_WAIT), 0,
		      "failed to lock defined mutex");
	zassert_equal(k_mutex_unlock(&kmutex), 0,
		      "failed to unlock defined mutex");
}

/**
 * @brief Test initializing a mutex
 *
 * @ingroup kernel_mutex_tests
 *
 * @see k_mutex_init()
 */
static void test_mutex_init(void)
{
	struct k_mutex mutex;

	/*This test case is to test whether the mutex is initialized
	 * properly by k_mutex_init.
	 */
	zassert_true(k_mutex_init(&mutex) == 0, "failed to initialize mutex");
	zassert_equal(k_mutex_lock(&mutex, K_NO_WAIT), 0,
		      "failed to lock initialized mutex");
	zassert_equal(k_mutex_unlock(&mutex), 0,
		      "failed to unlock initialized mutex");
}

static void thread_recursive_mutex(void *p1, void *p2, void *p3)
{
	ARG_UNUSED(p2);
	ARG_UNUSED(p3);
	struct k_mutex *mutex = p1;

	/* First lock should succeed */
	if (k_mutex_lock(mutex, K_NO_WAIT) != 0) {
		thread_ret = TC_FAIL;
		return;
	}

	/* Second lock should also succeed (recursive) */
	if (k_mutex_lock(mutex, K_NO_WAIT) != 0) {
		thread_ret = TC_FAIL;
		return;
	}

	k_mutex_unlock(mutex);
	k_mutex_unlock(mutex);
	thread_ret = TC_PASS;
}

/**
 * @brief Test recursive locking on a mutex
 * @ingroup kernel_mutex_tests
 * @see k_mutex_init(), k_mutex_lock(), k_mutex_unlock()
 */
static void test_mutex_recursive(void)
{
	struct k_mutex mutex;

	k_mutex_init(&mutex);
	thread_ret = TC_FAIL;

	k_tid_t tid = k_thread_create(&tdata, tstack, STACK_SIZE,
				      thread_recursive_mutex,
				      &mutex, NULL, NULL,
				      K_PRIO_PREEMPT(0), 0, K_NO_WAIT);

	k_thread_join(tid, K_FOREVER);

	zassert_equal(thread_ret, TC_PASS, "Recursive mutex test failed");
}

void test_main(void)
{
	ztest_test_suite(mutex_api,
			 ztest_unit_test(test_complex_inversion),
			 ztest_unit_test(test_mutex_define),
			 ztest_unit_test(test_mutex_init),
			 ztest_unit_test(test_mutex_recursive)
			 );
	ztest_run_test_suite(mutex_api);
}
